import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Karino2DIYApp.html","title":"Karino2DIYApp","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.1,"words":329},"filePathRelative":"Karino2DIYApp.md"}`),a={name:`Karino2DIYApp.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="karino2diyapp" tabindex="-1"><a class="header-anchor" href="#karino2diyapp"><span>Karino2DIYApp</span></a></h1><p><a href="./自作アプリ.html">自作アプリ</a></p><p>自分用のAndroidアプリを置くOrganizationとしてKarino2DIYAppというOrganizationを作った。<a href="https://github.com/orgs/Karino2DIYApp/repositories" target="_blank" rel="noopener noreferrer">Karino2DIYApp repositories</a></p><ul><li><a href="https://github.com/Karino2DIYApp/CropPagenate" target="_blank" rel="noopener noreferrer">Karino2DIYApp/CropPagenate</a> PDF Reader</li><li><a href="https://github.com/Karino2DIYApp/Musimegane" target="_blank" rel="noopener noreferrer">Karino2DIYApp/Musimegane: Android magnifier app</a> 虫眼鏡アプリ</li></ul><h2 id="モチベーション" tabindex="-1"><a class="header-anchor" href="#モチベーション"><span>モチベーション</span></a></h2><p>自作アプリをagentで作りまくるようになった結果、いちいちapkを作ったりするのが面倒になってきた。 ただ後でビルドが通らないとかで端末乗り換えの時に苦労しそうなので、 自分用アプリはOrganizationの下に入れてapk作成を自動化する事にする。</p><p>開発はデバッグ実行しながら開発していくのでDebug版がどれかの端末には入ったままになる。 そしてrelease用のworkflowを定義しておいて、適当なタイミングでv3とかタグをつけてpushすると apkがReleaseページに出来る、みたいな感じになっている。</p><p>このDIYAppは基本的には自分しか使わないので、いろいろ単純化した方針でやっていきたい。</p><h2 id="バージョンは単なる連番でv1-v2-v3と進める" tabindex="-1"><a class="header-anchor" href="#バージョンは単なる連番でv1-v2-v3と進める"><span>バージョンは単なる連番でv1, v2, v3と進める</span></a></h2><p>バージョンコードとバージョンネームを完全に単なるintの連番（1とか2とか）として、スクリプトから上げやすくする。 そしてタグもv1, v2とvで始めたバージョン番号とする。</p><h2 id="タグをpushしたらapkがreleaseページに出来る" tabindex="-1"><a class="header-anchor" href="#タグをpushしたらapkがreleaseページに出来る"><span>タグをpushしたらapkがReleaseページに出来る</span></a></h2><p>このOrganizationでは基本的にはapkのリリースを共通のワークフローテンプレートを使ってリリースする。 release.ymlは以下の移行手順に書いてあるものを使う。</p><h2 id="新規レポジトリをこれに加える" tabindex="-1"><a class="header-anchor" href="#新規レポジトリをこれに加える"><span>新規レポジトリをこれに加える</span></a></h2><ul><li><a href="https://github.com/orgs/Karino2DIYApp/repositories" target="_blank" rel="noopener noreferrer">Karino2DIYApp repositories</a> から新規レポジトリを作成、この時privateになるとCIがコケるので注意</li><li>.github/workflows下にrelease.ymlを作る、下のセクションのシェルスクリプトを実行</li><li>versionNameを1に変えてv1タグをpush</li></ul><p>ちなみにprivateだったりOrg下では無くkarino2下になっているとCIがこけた時のメッセージは、以下みたいにTag numberうんちゃら、と出る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&quot;/home/runner/work/CropPagenate/CropPagenate/release-key.jks&quot;: Tag number over 30 is not supported</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="既存レポジトリの移行手順" tabindex="-1"><a class="header-anchor" href="#既存レポジトリの移行手順"><span>既存レポジトリの移行手順</span></a></h2><ul><li>レポジトリのSettings＞General＞Danger Zone＞Transfer ownershipでKarino2DIYAppにする</li><li>Settings＞ActionsでWorkflow permissionsをRead and writeに変更</li><li>ローカルのgitのremoteを以下の感じでセット</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% git remote -v</span>
<span class="line">origin	git@github.com:karino2/SAFToDo.git (fetch)</span>
<span class="line">origin	git@github.com:karino2/SAFToDo.git (push)</span>
<span class="line">% git remote set-url origin git@github.com:Karino2DIYApp/SAFToDo.git</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>そして以下を実行してrelease.ymlを作る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ mkdir -p .github/workflows &amp;&amp; cat &lt;&lt; &#39;EOF&#39; &gt; .github/workflows/release.yml</span>
<span class="line">name: Build and Release APK</span>
<span class="line"></span>
<span class="line">on:</span>
<span class="line">  push:</span>
<span class="line">    tags:</span>
<span class="line">      - &#39;v*&#39;</span>
<span class="line"></span>
<span class="line">jobs:</span>
<span class="line">  call-shared-build:</span>
<span class="line">    uses: Karino2DIYApp/.github/.github/workflows/android-build.yml@main</span>
<span class="line">    secrets: inherit</span>
<span class="line">EOF</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="organizationに入れないけど同じworkflowを実行したい場合の設定" tabindex="-1"><a class="header-anchor" href="#organizationに入れないけど同じworkflowを実行したい場合の設定"><span>Organizationに入れないけど同じworkflowを実行したい場合の設定</span></a></h2><ul><li>PngNoteのrelease.ymlを持ってくる <a href="https://github.com/karino2/PngNote/blob/main/.github/workflows/release.yml" target="_blank" rel="noopener noreferrer">PngNote/.github/workflows/release.yml at main · karino2/PngNote</a></li><li>Secrets＞Secrets and variables＞ActionsのSecretsタブの下のRepository secretsで以下を指定</li><li>Settings＞ActionsでWorkflow permissionsをRead and writeに変更</li></ul><table><thead><tr><th>名前</th><th>何を設定するか</th></tr></thead><tbody><tr><td>SIGNING_KEY</td><td>下のpbcopy</td></tr><tr><td>SIGNING_KEY_ALIAS</td><td>release</td></tr><tr><td>SIGNING_KEY_PASSWORD</td><td>パスワードマネージャから</td></tr><tr><td>SIGNING_STORE_PASSWORD</td><td>パスワードマネージャから</td></tr></tbody></table><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">base64 -i  ~/your/pass/to/release_keystore_for_github_actions2.jks | tr -d &#39;\\n&#39; | pbcopy</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};